private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_zk_cred_bbs_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_zk_cred_bbs_checksum_func_blind_proof_gen_finalize() != 33447) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zk_cred_bbs_checksum_func_blind_proof_gen_init() != 10709) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zk_cred_bbs_checksum_func_blind_proof_verify() != 28899) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zk_cred_bbs_checksum_func_commit_finalize() != 30749) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zk_cred_bbs_checksum_func_commit_init() != 41686) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zk_cred_bbs_checksum_func_jwp_accept() != 47026) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zk_cred_bbs_checksum_func_jwp_build_presentation_header() != 63085) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zk_cred_bbs_checksum_func_jwp_committed_messages() != 7083) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zk_cred_bbs_checksum_func_jwp_inspect() != 32872) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zk_cred_bbs_checksum_func_jwp_present_finalize() != 4013) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zk_cred_bbs_checksum_func_jwp_present_init() != 38030) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zk_cred_bbs_checksum_func_jwp_verify() != 45226) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zk_cred_bbs_checksum_func_verify_blind_sign() != 2199) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_zk_cred_bbs_checksum_method_bbsffierror_message() != 7094) {
        return InitializationResult.apiChecksumMismatch
    }

    return InitializationResult.ok
}()

// Make the ensure init function public so that other modules which have external type references to
// our types can call it.
public func uniffiEnsureZkCredBbsInitialized() {
    switch initializationResult {
    case .ok:
        break
    case .contractVersionMismatch:
        fatalError("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    case .apiChecksumMismatch:
        fatalError("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
}

